    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, -0.1],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*55, 0.11, 2.1, 0.4],
