  const edge = Math.abs(reaction - shifted) * 12;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.2-t*0.5)*Math.cos(sy*0.18+t*0.3)*0.3)*1.5)*0.3;
  const blend = reaction*0.55 + cell*0.2 + act2*0.15 + cross*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,48],[8,25,75],[10,45,98],[13,70,112],[16,95,120],
    [20,122,128],[30,148,118],[60,162,100],[110,168,75],
    [165,162,55],[195,142,48],[210,115,52],[198,82,52],
